import java.nio.file.*;import java.util.*;public final class ProtocolApiEquivalent{public static void main(String[]a)throws Exception{var n=OpeningDelta.read(Files.readAllBytes(Path.of(a[0])),0);var o=OpeningDelta.read(Files.readAllBytes(Path.of(a[1])),0);if(!n.name.equals(o.name)||n.access!=o.access||!Objects.equals(n.superName,o.superName)||!n.interfaces.equals(o.interfaces)||n.fields.size()!=o.fields.size()||n.methods.size()!=o.methods.size())throw new IllegalStateException("Class shape differs "+n.name);for(var f:n.fields){var old=o.fields.stream().filter(x->x.name.equals(f.name)).findFirst().orElseThrow();if(!old.desc.equals(f.desc)||old.access!=f.access||!Objects.equals(old.value,f.value))throw new IllegalStateException("Field differs "+f.name);}for(var m:n.methods){var old=o.methods.stream().filter(x->OpeningDelta.key(x).equals(OpeningDelta.key(m))).findFirst().orElseThrow();if(old.access!=m.access||!OpeningDelta.eq(old,m))throw new IllegalStateException("Method semantics differ "+OpeningDelta.key(m));}System.out.println("PASS equivalent API/fields/all normalized method bodies "+n.name);}}